			written = { ["Cross the {area:814} bridges west out of {zone:1411} into the {zone:1413}. {area:385} in the east is an Alliance fort."] = "Cross the Southfury River bridges west out of Durotar into the Barrens. Northwatch Hold in the east is an Alliance fort.", ["Cross the {area:814} east from the northern {zone:1413} into {zone:1411}: Horde country, with guards at {area:362}, {area:367} and {zone:1454}."] = "Cross the Southfury River east from the northern Barrens into Durotar: Horde country, with guards at Razor Hill, Sen'jin Village and Orgrimmar.", ["Flight paths here: {area:392} (Bragok), {area:380} (Devrak), {area:378} ({npc:10378})."] = "Flight paths here: Ratchet (Bragok), Crossroads (Devrak), Camp Taurajo (Omusa Thunderhorn).", ["Fly to {area:378} and walk south through the {zone:1413} to the {area:485} down into {zone:1441}."] = "Fly to Camp Taurajo and walk south through the Barrens to the Great Lift down into Thousand Needles.", ["Go back west across the {zone:1413}; the road west from {area:378} climbs through the only pass into {zone:1412}, tauren country with guards at {area:222} and {zone:1456}."] = "Go back west across the Barrens; the road west from Camp Taurajo climbs through the only pass into Mulgore, tauren country with guards at Bloodhoof Village and Thunder Bluff.", ["Leave {zone:1412} by the same pass and ride south through the {zone:1413} to the {area:485} down into {zone:1441}. {area:484} is a Horde town."] = "Leave Mulgore by the same pass and ride south through the Barrens to the Great Lift down into Thousand Needles. Freewind Post is a Horde town.", ["Leave {zone:1412} by the same pass, ride north through the {zone:1413} and west at {area:1702} into the {zone:1442}. {area:460} is the Horde town; {area:467} in the north is Alliance."] = "Leave Mulgore by the same pass, ride north through the Barrens and west at Honor's Stand into the Stonetalon Mountains. Sun Rock Retreat is the Horde town; Stonetalon Peak in the north is Alliance.", ["The road east out of south-eastern Stonetalon comes down into the {zone:1413} at {area:1702}. {area:380} and {area:378} are Horde towns; {area:392} is a neutral port."] = "The road east out of south-eastern Stonetalon comes down into the Barrens at Honor's Stand. The Crossroads and Camp Taurajo are Horde towns; Ratchet is a neutral port.", ["{area:485}"] = "The Great Lift" },
